const normalize = (value) => value.trim().replace(/\s+/g, ' ');

export function translateInterface(value) {
  const key = normalize(value);
  let translated = ES[key];
  if (!translated && key.endsWith(' · CrafterWIKI')) {
    const title = key.slice(0, -14);
    if (ES[title]) translated = `${ES[title]} · CrafterWIKI`;
  }
  if (!translated) {
    const suffix = key.match(/^(.*?)( [→↗])$/);
    if (suffix && ES[suffix[1]]) translated = ES[suffix[1]] + suffix[2];
  }
  if (!translated) {
    translated = key
      .replace(/^(\d+) results? · showing (\d+)$/, (_, n, shown) => `${n} resultado${n === '1' ? '' : 's'} · mostrando ${shown}`)
      .replace(/^(\d+) results?$/, '$1 resultados')
      .replace(/^Featured project · (\d+)$/, 'Proyecto destacado · $1')
      .replace(/^Watch (.+) demo on YouTube$/, 'Ver la demo de $1 en YouTube')
      .replace(/^(\d+) organizer sources$/, '$1 fuentes del organizador')
      .replace(/^(.+) — organizer results ↗$/, '$1 — resultados del organizador ↗')
      .replace(/^Confidence:\s*(.*)$/, 'Confianza: $1')
      .replace(/^Press the button\. Draws come from (\d+) confirmed winners and finalists\.$/, 'Pulsa el botón. La selección incluye $1 ganadores y finalistas confirmados.')
      .replace(/^(\d+) similar situations?, ranked by weighted facet overlap \(domains and mechanisms count most\), then placement\.$/, '$1 situaciones similares, ordenadas por coincidencia de filtros (áreas y mecanismos pesan más) y después por reconocimiento.');
    for (const label of ['Grand winner', 'Podium', 'Award winner', 'Runner-up', 'Finalist', 'Public vote', 'Featured', 'Reported · unverified', 'Submitted', 'Unknown']) {
      if (key.startsWith(`${label} ·`) || key.startsWith(`${label} #`)) {
        translated = ES[label] + key.slice(label.length).replace(/ votes/g, ' votos');
        break;
      }
    }
  }
  return translated && translated !== key ? value.replace(value.trim(), translated) : value;
}

export function initLanguage() {
  if (window.__crafterLanguageInitialized) return;
  window.__crafterLanguageInitialized = true;
  let language = navigator.language?.toLowerCase().startsWith('es') ? 'es' : 'en';
  try { const saved = localStorage.getItem('cw-language'); if (saved === 'en' || saved === 'es') language = saved; } catch { /* Private mode can disable storage. */ }
  const originals = new WeakMap();
  const attributes = new WeakMap();
  const excluded = 'script,style,pre,code,[translate="no"],[data-no-translate],#language-toggle';
  const translateNode = (node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      if (!node.parentElement || node.parentElement.closest(`${excluded},textarea`)) return;
      const prior = originals.get(node);
      const current = node.nodeValue;
      const original = !prior || current !== prior.rendered ? current : prior.original;
      const rendered = language === 'es' ? translateInterface(original) : original;
      originals.set(node, { original, rendered });
      if (current !== rendered) node.nodeValue = rendered;
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      if (node.matches(excluded)) return;
      const prior = attributes.get(node) || {};
      for (const name of ['placeholder', 'aria-label', 'title', 'alt']) {
        if (!node.hasAttribute(name)) continue;
        const current = node.getAttribute(name);
        const original = !prior[name] || current !== prior[name].rendered ? current : prior[name].original;
        const rendered = language === 'es' ? translateInterface(original) : original;
        prior[name] = { original, rendered };
        if (current !== rendered) node.setAttribute(name, rendered);
      }
      attributes.set(node, prior);
      if (node.matches('textarea')) return;
      for (const child of node.childNodes) translateNode(child);
    }
  };
  const observer = new MutationObserver((records) => {
    observer.disconnect();
    for (const record of records) {
      if (record.type === 'childList') for (const node of record.addedNodes) translateNode(node);
      else translateNode(record.target);
    }
    observe();
  });
  const observe = () => observer.observe(document.documentElement, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ['placeholder', 'aria-label', 'title', 'alt'] });
  const apply = () => {
    observer.disconnect();
    document.documentElement.lang = language;
    translateNode(document.documentElement);
    observe();
    window.dispatchEvent(new CustomEvent('crafter-language-applied', { detail: language }));
  };
  window.addEventListener('crafter-language', (event) => {
    if (event.detail !== 'en' && event.detail !== 'es') return;
    language = event.detail;
    try { localStorage.setItem('cw-language', language); } catch { /* Translation still works without persistence. */ }
    apply();
  });
  apply();
}
